from itertools import *
cnt = 0
for p in product('0123456789ABCD', repeat=5):
    num = ''.join(p)
    if num[0] != '0':
        for x in 'ABCD':
            num = num.replace(x, 'A')
        for x in '13579':
            num = num.replace(x, '1')
        if '1A' not in num and 'A1' not in num:
            cnt += 1
print(cnt)

